// Enumerate FSKit's ObjC classes, protocols, and methods from the live runtime.
#import <Foundation/Foundation.h>
#import <objc/runtime.h>
#import <dlfcn.h>

static void dumpMethods(Class c, BOOL meta) {
    unsigned int n = 0;
    Method *ms = class_copyMethodList(meta ? object_getClass(c) : c, &n);
    for (unsigned int i = 0; i < n; i++) {
        printf("  %s%s\n", meta ? "+" : "-", sel_getName(method_getName(ms[i])));
    }
    free(ms);
}

int main(void) {
    void *h = dlopen("/System/Library/Frameworks/FSKit.framework/FSKit", RTLD_NOW);
    if (!h) { printf("dlopen failed: %s\n", dlerror()); return 1; }

    unsigned int count = 0;
    const char **names = objc_copyClassNamesForImage("/System/Library/Frameworks/FSKit.framework/Versions/A/FSKit", &count);
    if (!names || count == 0) {
        // shared-cache path may differ; fall back to scanning all classes for FS prefix
        int total = objc_getClassList(NULL, 0);
        Class *all = malloc(sizeof(Class) * total);
        total = objc_getClassList(all, total);
        printf("== classes (prefix scan, %d total) ==\n", total);
        for (int i = 0; i < total; i++) {
            const char *cn = class_getName(all[i]);
            if (strncmp(cn, "FS", 2) == 0 || strstr(cn, "fskit")) {
                printf("CLASS %s : %s\n", cn, class_getSuperclass(all[i]) ? class_getName(class_getSuperclass(all[i])) : "nil");
                dumpMethods(all[i], NO);
                dumpMethods(all[i], YES);
            }
        }
        free(all);
    } else {
        printf("== classes (%u) ==\n", count);
        for (unsigned int i = 0; i < count; i++) {
            Class c = objc_getClass(names[i]);
            printf("CLASS %s : %s\n", names[i], c && class_getSuperclass(c) ? class_getName(class_getSuperclass(c)) : "nil");
            if (c) { dumpMethods(c, NO); dumpMethods(c, YES); }
        }
        free(names);
    }

    unsigned int pc = 0;
    Protocol *__unsafe_unretained *protos = objc_copyProtocolList(&pc);
    printf("== protocols with FS prefix (%u total) ==\n", pc);
    for (unsigned int i = 0; i < pc; i++) {
        const char *pn = protocol_getName(protos[i]);
        if (strncmp(pn, "FS", 2) != 0) continue;
        printf("PROTOCOL %s\n", pn);
        for (int req = 0; req <= 1; req++) {
            for (int inst = 0; inst <= 1; inst++) {
                unsigned int mc = 0;
                struct objc_method_description *mds = protocol_copyMethodDescriptionList(protos[i], req, inst, &mc);
                for (unsigned int j = 0; j < mc; j++)
                    printf("  %s%s%s\n", inst ? "-" : "+", req ? "" : "(opt) ", sel_getName(mds[j].name));
                free(mds);
            }
        }
    }
    free(protos);
    return 0;
}

// Print type encodings for the macOS 27 FSKit additions.
#import <Foundation/Foundation.h>
#import <objc/runtime.h>
#import <dlfcn.h>

static void enc(Class c, const char *sel) {
    Method m = class_getInstanceMethod(c, sel_registerName(sel));
    printf("-[%s %s] :: %s\n", class_getName(c), sel, m ? method_getTypeEncoding(m) : "MISSING");
}

int main(void) {
    dlopen("/System/Library/Frameworks/FSKit.framework/FSKit", RTLD_NOW);

    enc(objc_getClass("FSVolume"), "setCacheStateForItem:cacheMode:coherencyType:coherencyAction:");
    enc(objc_getClass("FSUserClient"), "setCacheStateWithLiveFH:mountReference:cacheMode:coherencyType:coherencyAction:");
    enc(objc_getClass("FSClient"), "mountSingleVolumeForResource:bundleID:mountPath:options:completionHandler:");
    enc(objc_getClass("FSClient"), "mountSingleVolumeForResource:bundleID:options:completionHandler:");
    enc(objc_getClass("FSVolumeConnector"), "openItem:modes:cacheMode:auditToken:requestID:replyHandler:");

    Protocol *p = objc_getProtocol("FSVolumeDataCacheHandler");
    const char *sels[] = {"openItem:modes:cacheMode:context:replyHandler:",
                          "upgradeItem:cacheMode:context:replyHandler:",
                          "closeItem:context:replyHandler:",
                          "isDataCacheInhibited"};
    for (int i = 0; i < 4; i++) {
        for (int req = 0; req <= 1; req++) {
            struct objc_method_description d = protocol_getMethodDescription(p, sel_registerName(sels[i]), req, YES);
            if (d.name) printf("proto %s%s :: %s\n", req ? "" : "(opt) ", sels[i], d.types);
        }
    }
    // Also list any FSItem/FSVolume props added around caching
    unsigned int n = 0;
    objc_property_t *props = class_copyPropertyList(objc_getClass("FSVolume"), &n);
    for (unsigned int i = 0; i < n; i++)
        printf("FSVolume prop: %s :: %s\n", property_getName(props[i]), property_getAttributes(props[i]));
    return 0;
}

// Extended type encodings (incl. block signatures) + FSKit __TEXT string dump.
#import <Foundation/Foundation.h>
#import <objc/runtime.h>
#import <dlfcn.h>
#import <mach-o/dyld.h>
#import <mach-o/getsect.h>

extern const char *_protocol_getMethodTypeEncoding(Protocol *p, SEL sel, BOOL required, BOOL instance);

static void pext(const char *proto, const char *sel) {
    Protocol *p = objc_getProtocol(proto);
    for (int req = 0; req <= 1; req++) {
        const char *e = _protocol_getMethodTypeEncoding(p, sel_registerName(sel), req, YES);
        if (e) printf("EXT %s %s :: %s\n", proto, sel, e);
    }
}

int main(int argc, char **argv) {
    dlopen("/System/Library/Frameworks/FSKit.framework/FSKit", RTLD_NOW);

    pext("FSVolumeDataCacheHandler", "openItem:modes:cacheMode:context:replyHandler:");
    pext("FSVolumeDataCacheHandler", "upgradeItem:cacheMode:context:replyHandler:");
    pext("FSVolumeDataCacheHandler", "closeItem:context:replyHandler:");
    pext("FSVolumeOpenCloseHandler", "openItem:modes:context:replyHandler:");
    pext("FSVolumeXPC", "openItem:modes:cacheMode:auditToken:requestID:replyHandler:");

    // Dump __cstring + __objc_methname of the loaded FSKit image
    if (argc > 1) {
        for (uint32_t i = 0; i < _dyld_image_count(); i++) {
            const char *name = _dyld_get_image_name(i);
            if (!strstr(name, "FSKit.framework")) continue;
            const struct mach_header_64 *mh = (const struct mach_header_64 *)_dyld_get_image_header(i);
            unsigned long size = 0;
            const char *sects[][2] = {{"__TEXT","__cstring"},{"__TEXT","__oslogstring"}};
            for (int s = 0; s < 2; s++) {
                uint8_t *data = getsectiondata(mh, sects[s][0], sects[s][1], &size);
                if (!data) { printf("## no %s\n", sects[s][1]); continue; }
                printf("## %s (%lu bytes)\n", sects[s][1], size);
                unsigned long off = 0;
                while (off < size) {
                    const char *str = (const char *)(data + off);
                    size_t len = strnlen(str, size - off);
                    if (len > 3) printf("%s\n", str);
                    off += len + 1;
                }
            }
        }
    }
    return 0;
}

// Dump methods+properties of the FSKit result/negotiation classes.
#import <Foundation/Foundation.h>
#import <objc/runtime.h>
#import <dlfcn.h>

static void dumpClass(const char *cn) {
    Class c = objc_getClass(cn);
    if (!c) { printf("CLASS %s MISSING\n", cn); return; }
    printf("CLASS %s : %s\n", cn, class_getName(class_getSuperclass(c)));
    unsigned int n = 0;
    objc_property_t *props = class_copyPropertyList(c, &n);
    for (unsigned int i = 0; i < n; i++)
        printf("  prop %s :: %s\n", property_getName(props[i]), property_getAttributes(props[i]));
    free(props);
    n = 0;
    Method *ms = class_copyMethodList(c, &n);
    for (unsigned int i = 0; i < n; i++)
        printf("  -%s :: %s\n", sel_getName(method_getName(ms[i])), method_getTypeEncoding(ms[i]));
    free(ms);
    n = 0;
    ms = class_copyMethodList(object_getClass(c), &n);
    for (unsigned int i = 0; i < n; i++)
        printf("  +%s :: %s\n", sel_getName(method_getName(ms[i])), method_getTypeEncoding(ms[i]));
    free(ms);
}

int main(void) {
    dlopen("/System/Library/Frameworks/FSKit.framework/FSKit", RTLD_NOW);
    dumpClass("FSOpenItemResult");
    dumpClass("FSUpgradeItemResult");
    dumpClass("FSItem");
    dumpClass("FSContext");
    return 0;
}

