// Focused brute-force of the setCacheStateForItem coherency triple.
// Each iteration re-establishes a stale mmap'd page (fill A -> fault ->
// server-mutate to D, no inval), fires setCacheStateForItem(mode,type,
// action), and checks whether the mapped page flips to 'D'. A hit means
// that triple is the kernel-page invalidation directive.
//
// Usage: g5sweep <mountRoot> <dataFile> <maxMode> <maxType> <maxAction>

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/xattr.h>
#include <sys/mman.h>
#include <time.h>

static int cmd(const char *root, const char *c) {
    return setxattr(root, "g5.cmd", c, strlen(c), 0, 0);
}

int main(int argc, char **argv) {
    if (argc < 6) { fprintf(stderr, "usage: %s root file maxMode maxType maxAction\n", argv[0]); return 2; }
    const char *root = argv[1], *file = argv[2];
    int maxMode = atoi(argv[3]), maxType = atoi(argv[4]), maxAction = atoi(argv[5]);
    const char *base = strrchr(file, '/'); base = base ? base + 1 : file;
    char buf[128];
    int hits = 0;

    printf("== setCacheStateForItem invalidation brute-force ==\n");
    for (int mode = 0; mode <= maxMode; mode++)
    for (int type = 0; type <= maxType; type++)
    for (int action = 0; action <= maxAction; action++) {
        // Re-establish stale cached page.
        snprintf(buf, sizeof(buf), "fill %s A 65536", base); cmd(root, buf);
        int fd = open(file, O_RDONLY);
        unsigned char *m = mmap(NULL, 65536, PROT_READ, MAP_SHARED, fd, 0);
        if (m == MAP_FAILED) { close(fd); continue; }
        volatile unsigned char s = m[0]; (void)s;   // fault in
        snprintf(buf, sizeof(buf), "mutate %s D", base); cmd(root, buf);
        usleep(5000);
        if (m[0] != 'A') { munmap((void*)m, 65536); close(fd); continue; }  // wasn't cached

        // Fire the candidate invalidation.
        snprintf(buf, sizeof(buf), "setcache %s %d %d %d", base, mode, type, action);
        cmd(root, buf);
        int flipped = 0;
        for (int i = 0; i < 2000; i++) { if (m[0] == 'D') { flipped = 1; break; } usleep(100); }
        if (flipped) { printf("  HIT mode=%d type=%d action=%d -> page invalidated\n", mode, type, action); hits++; }
        munmap((void*)m, 65536); close(fd);
    }
    printf("total hits: %d\n", hits);
    return 0;
}

// Careful, single-triple invalidation trial for gate 5.
// Repeats N independent trials of: fill A -> mmap+fault -> confirm cached ->
// server-mutate to D (no inval) -> confirm still stale -> setCacheStateForItem
// (mode,type,action) -> poll mapped page for the flip to D. Reports the
// cached-rate, invalidation-landed-rate, and latency distribution so a flaky
// vs reliable primitive is distinguishable.
//
// Usage: g5inval <mountRoot> <dataFile> <mode> <type> <action> <trials>

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/xattr.h>
#include <sys/mman.h>
#include <time.h>

static uint64_t now_ns(void) { return clock_gettime_nsec_np(CLOCK_MONOTONIC_RAW); }
static int cmd(const char *root, const char *c) { return setxattr(root, "g5.cmd", c, strlen(c), 0, 0); }

int main(int argc, char **argv) {
    if (argc < 7) { fprintf(stderr, "usage: %s root file mode type action trials\n", argv[0]); return 2; }
    const char *root = argv[1], *file = argv[2];
    int mode = atoi(argv[3]), type = atoi(argv[4]), action = atoi(argv[5]), trials = atoi(argv[6]);
    const char *base = strrchr(file, '/'); base = base ? base + 1 : file;
    char buf[128];

    int cached = 0, landed = 0;
    double lat[4096]; int nl = 0;

    printf("== gate-5 invalidation trial: setCacheStateForItem(mode=%d type=%d action=%d), %d trials ==\n",
           mode, type, action, trials);
    for (int t = 0; t < trials; t++) {
        snprintf(buf, sizeof(buf), "fill %s A 65536", base); cmd(root, buf);
        int fd = open(file, O_RDONLY);
        unsigned char *m = mmap(NULL, 65536, PROT_READ, MAP_SHARED, fd, 0);
        if (m == MAP_FAILED) { close(fd); continue; }
        volatile unsigned char s = m[0]; (void)s;         // fault -> cache
        usleep(2000);
        snprintf(buf, sizeof(buf), "mutate %s D", base); cmd(root, buf);  // server change, no inval
        usleep(10000);
        if (m[0] != 'A') { munmap((void*)m, 65536); close(fd); continue; }  // not cached this trial
        cached++;

        snprintf(buf, sizeof(buf), "setcache %s %d %d %d", base, mode, type, action);
        uint64_t t0 = now_ns();
        cmd(root, buf);
        int flip = 0;
        for (int i = 0; i < 3000; i++) { if (m[0] == 'D') { flip = 1; break; } usleep(100); }
        if (flip) { landed++; lat[nl++] = (now_ns() - t0) / 1e6; }
        munmap((void*)m, 65536); close(fd);
    }
    printf("cached (page held stale): %d/%d\n", cached, trials);
    printf("invalidation landed:      %d/%d cached\n", landed, cached);
    if (nl) {
        // simple sort for percentiles
        for (int i = 0; i < nl; i++) for (int j = i+1; j < nl; j++) if (lat[j] < lat[i]) { double tmp=lat[i]; lat[i]=lat[j]; lat[j]=tmp; }
        double sum = 0; for (int i = 0; i < nl; i++) sum += lat[i];
        printf("latency ms: min=%.3f p50=%.3f p95=%.3f max=%.3f mean=%.3f\n",
               lat[0], lat[nl/2], lat[(int)(nl*0.95)], lat[nl-1], sum/nl);
    }
    return 0;
}

